import { readFileSync, writeFileSync } from 'node:fs';

const catalog = new URL('../src/locales/en/messages.po', import.meta.url);
const output = new URL('../src/message-ids.generated.ts', import.meta.url);

// Ids are explicit dotted words on one line, as `lingui extract` writes them; the empty msgid is the header.
const ids = [...readFileSync(catalog, 'utf8').matchAll(/^msgid "([\w.-]+)"$/gm)].map(([, id]) => id).toSorted();

writeFileSync(
  output,
  [
    '// Generated by scripts/message-ids.ts from src/locales/en/messages.po (pnpm run messages): do not edit.',
    '',
    "declare module '@lingui/core' {",
    '  interface Register {',
    `    messageIds:\n${ids.map((id) => `      | '${id}'`).join('\n')};`,
    '  }',
    '}',
    '',
  ].join('\n'),
);
